const items = $input.all();

console.log('🚨 ===== ERROR CAUGHT =====');
console.log('📊 Total items received:', items.length);

// Error Trigger gibt die Error-Daten im ersten Item
const errorItem = items[0].json;

console.log('📋 Error Item Keys:', Object.keys(errorItem));
console.log('📋 Full Error Object:', JSON.stringify(errorItem, null, 2));

// ✅ Extract error details (n8n Error Trigger structure)
const errorDetails = {
  timestamp: new Date().toISOString(),

  // Workflow Info
  workflowName: $workflow.name || 'Unknown Workflow',
  workflowId: $workflow.id || 'unknown',

  // Execution Info
  executionId: $execution.id || 'unknown',
  executionMode: $execution.mode || 'unknown',

  // Error Info
  errorMessage: errorItem.error?.message || errorItem.message || 'No error message',
  errorStack: errorItem.error?.stack || errorItem.stack || 'No stack trace',
  errorDescription: errorItem.error?.description || errorItem.description || '',

  // Node Info
  nodeName: errorItem.node?.name || 'Unknown Node',
  nodeType: errorItem.node?.type || 'Unknown',
  nodeParameters: errorItem.node?.parameters || {},

  // Try to extract input data that caused the error
  inputData: errorItem.error?.context?.data || errorItem.inputData || null,

  // Try to extract user data from execution data
  userData: {
    userEmail: errorItem.inputData?.userEmail || 
               errorItem.error?.context?.userEmail || 
               'unknown',
    userName: errorItem.inputData?.userName || 
              errorItem.error?.context?.userName || 
              'unknown',
    title: errorItem.inputData?.title || 
           errorItem.error?.context?.title || 
           'unknown',
    source: errorItem.inputData?.source || 
            errorItem.error?.context?.source || 
            'unknown'
  }
};

console.log('✅ Parsed Error Details:', errorDetails);
console.log('📧 User Email:', errorDetails.userData.userEmail);
console.log('🔧 Failed Node:', errorDetails.nodeName);
console.log('❌ Error Message:', errorDetails.errorMessage);

return {
  json: errorDetails
};

